let numPetalLayers = 5;
let basePetalCount = 6;
let rotationSpeed = 0.005;

function setup() {
  createCanvas(1280, 720);
  colorMode(HSB, 360, 100, 100, 1.0);
  background(0);
}

function draw() {
  // 建立半透明背景以產生發光拖尾
  background(0, 0, 0, 0.08);

  let beatVal = window.beatEnergy || 0.0;
  let lowVal = window.audioLow || 0.0;
  let midVal = window.audioMid || 0.0;
  let highVal = window.audioHigh || 0.0;

  // 變種特有：引力坍塌因子
  let collapse = lowVal > 0.65 ? map(lowVal, 0.65, 1.0, 1.0, 0.35) : 1.0;

  translate(width / 2, height / 2);

  // 隨時間與音效自轉
  let targetSpeed = rotationSpeed * (1.0 + beatVal * 3.5);
  rotate(frameCount * targetSpeed);

  let baseColor = 220; // 預設藍色系
  if (window.currentChordColor) {
    let chordC = color(window.currentChordColor);
    baseColor = hue(chordC);
  }

  // 繪製多層花瓣
  for (let i = 0; i < numPetalLayers; i++) {
    push();
    // 每一層稍微旋轉 offset
    rotate(i * (TWO_PI / numPetalLayers) * 0.15 + frameCount * 0.001);

    // 花瓣基本尺寸與低音連動，並受到引力坍塌因子影響
    let maxRadius = (160 + i * 45) * (1.0 + lowVal * 0.35) * collapse;
    let minRadius = (40 + i * 15) * (1.0 - lowVal * 0.15) * collapse;

    let petalN = basePetalCount + (i % 2 == 0 ? 1 : -1);

    noFill();
    // 發光霓虹線條
    let hueVal = (baseColor + i * 18 + sin(frameCount * 0.02) * 15) % 360;
    stroke(hueVal, 85, 95, 0.18 + beatVal * 0.25);
    strokeWeight(1.5 + midVal * 2.5 + (i * 0.4));

    beginShape();
    let numPoints = 240;
    for (let j = 0; j < numPoints; j++) {
      let theta = map(j, 0, numPoints, 0, TWO_PI);

      // 玫瑰線幾何內核
      let r = map(sin(petalN * theta), -1, 1, minRadius, maxRadius);

      // 導入 Perlin Noise 流場波動
      let noiseVal = noise(
        cos(theta) * 1.5 + frameCount * 0.015,
        sin(theta) * 1.5 + frameCount * 0.015,
        i * 0.3
      );

      // 高音調幅：花瓣邊緣產生絲狀高頻抖動
      let perturb = (noiseVal - 0.5) * (30 + highVal * 65);
      let finalR = r + perturb;

      // 將極坐標轉換為笛卡爾坐標
      let x = finalR * cos(theta);
      let y = finalR * sin(theta);

      // 變種特有：引力旋渦扭曲
      if (lowVal > 0.65) {
        let twist = map(lowVal, 0.65, 1.0, 0.0, 0.45);
        let distFactor = map(finalR, 0, maxRadius, 1.0, 0.1);
        let currentTheta = theta + twist * distFactor;
        x = finalR * cos(currentTheta);
        y = finalR * sin(currentTheta);
      }

      vertex(x, y);
    }
    endShape(CLOSE);
    pop();
  }
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

